INSERT INTO app_settings (setting_key,setting_value) VALUES ('about','MyoSkills объединяет домашние занятия и обратную связь специалистов. Пациент получает персональный маршрут, а команда врачей — общую картину занятий и лечения.');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('contact_email','');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('contact_phone','');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('contact_address','');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('legal_company','');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('about_en','MyoSkills connects at-home practice with professional feedback. Patients follow a personal route, and their care team shares the activity and treatment history.');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('landing_title_en','Your skills. Your galaxy.');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('tariffs_message_en','The first release is free to use. Pricing will be introduced when paid features are launched.');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('services_en','[{"title": "Your personal route", "text": "Your myotherapist assigns exercises and opens new missions after review."}, {"title": "Feedback on your videos", "text": "Upload your practice and receive feedback from your specialist."}, {"title": "Your care team", "text": "Related specialists share the treatment history within their access rights."}]');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('faq_en','[{"q": "Who opens new exercises?", "a": "A verified myotherapist in your care team. Access follows your assignments."}, {"q": "Can I record a video on the site?", "a": "Yes, in a supported browser over HTTPS. You can also upload a prerecorded file."}, {"q": "Who sees my photos and videos?", "a": "You, authorized members of your care team, and the administrator. Other patients cannot access them."}, {"q": "How do rewards work?", "a": "Practice earns fuel; doctor approval earns XP and stars. Your myotherapist opens advanced exercises."}]');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('shop_links_en','[]');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('landing_title','Твой навык. Твоя галактика.');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('tariffs_message','На первом этапе доступ к сервису бесплатный. Тарифы появятся после запуска платных возможностей.');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('shop_links','[]');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('services','[{"title": "Персональный маршрут", "text": "Миотерапевт выбирает упражнения и открывает новые миссии после проверки."}, {"title": "Обратная связь по видео", "text": "Загружай выполнение и получай комментарии специалиста."}, {"title": "Команда рядом", "text": "Смежные врачи видят историю лечения в пределах своих прав."}]');
INSERT INTO app_settings (setting_key,setting_value) VALUES ('faq','[{"q": "Кто открывает новые упражнения?", "a": "Верифицированный миотерапевт из вашей команды. Доступ определяется назначением."}, {"q": "Можно ли записать видео прямо на сайте?", "a": "Да, если браузер поддерживает запись и сайт открыт по HTTPS. Готовый файл можно загрузить отдельно."}, {"q": "Кто видит мои фотографии и видео?", "a": "Вы, специалисты вашей команды и администратор с правом доступа. Другие пациенты не получают доступ."}, {"q": "За что выдаются награды?", "a": "Топливо отмечает выполнение, звёзды и опыт — подтверждение врача. Новые уровни открывает миотерапевт."}]');
